/**
 * Open the live stream
 *
 * Opens the one server-sent events stream an app holds, naming every
 * channel its screens listen to, comma-separated, from the closed
 * vocabulary (see Live streams on the portal). A name no channel produces
 * is `400` (`channel_unknown`) with `errors` by position. Private channels
 * are authorised when the stream opens, against the caller's own facts,
 * never cached, and again every 30 seconds while it stays open: an open
 * naming a channel the caller may not hear is refused as a whole (`401`,
 * `403` or `404`, `errors` pointing at the refused channel's position), so
 * the client drops it and opens again. Public channels (`broadcast`,
 * `store-{location_id}-menu`) need no credential.
 *
 * Who hears what follows the token's surface (`aud`) and what its holder
 * holds now. A customer token hears `private-broadcast`, its own
 * `private-customer-{customer_id}-orders` and the
 * `private-order-{order_id}` of an order it placed; a Partner token hears a
 * Location's channels only for a Location of a partner it belongs to (any
 * other is `404`, like one that does not exist), the notices with
 * `notice:read` there, the orders, kitchen and tables with `order:read`
 * there, the catalogue with `catalog:read` there, and its partner's
 * agents and deliveries (`private-partner-{partner_id}-agents`,
 * `private-partner-{partner_id}-deliveries`) with `dispatch:read` in the
 * partner; a Mission Control token hears the network's orders
 * (`private-orders`) with `order:read`, agents (`private-agents`) with
 * `agent:read` and deliveries (`private-deliveries`) with
 * `dispatch:read`, and never a single Location; an Agent token hears its
 * own task channel. Anything else is `403`.
 *
 * | Event            | Data                 | When                                                        |
 * | ---------------- | -------------------- | ----------------------------------------------------------- |
 * | `snapshot`       | `AgentsSnapshot`     | On open, per agent channel                                  |
 * | `resync`         | `Resync`             | On open, per other channel, unless resumed; after a fan-out outage |
 * | `signal`         | `Signal`             | Something changed; refetch it unless you hold the version   |
 * | `agent.position` | `AgentPositionFrame` | An agent moved                                              |
 * | `agent.status`   | `AgentStatusFrame`   | An agent went online or offline                             |
 * | `courier.position` | `CourierPositionFrame` | On an order's channel, its courier moved: from collection until delivery only |
 * | `heartbeat`      | empty                | Every 15 seconds                                            |
 * | `close`          | `Close`              | The platform ends the stream: `token_expired`, `revoked`, `replaced` |
 *
 * Signals carry an `id`, the position of the signal in the platform's
 * fan-out, and the frames that open a stream carry the position it opened
 * at. A client that reconnects with the last `id` it received, in the
 * `Last-Event-ID` header (which `EventSource` sends by itself) or in
 * `last_event_id`, resumes: the signals of its channels it missed are sent
 * first, with their ids, and no `resync` is sent for those channels. When
 * the position is no longer held (the platform keeps the latest ten
 * thousand signals), or the id is not one it gave, the stream starts
 * again with a `snapshot` or `resync` per channel, as for a new client.
 * Agent and courier positions are never replayed: an agent channel always
 * opens with a fresh `snapshot`.
 *
 * The stream lives no longer than the access token; a revoked session, a
 * removed membership or a permission no longer held closes it within a
 * minute with `revoked`; a connection with the same `client_id`, or the
 * fifth connection of a session, replaces the oldest. Treat 45 seconds
 * without a frame as a lost connection and reconnect with backoff.
 *
 */
export const openLiveStream = <ThrowOnError extends boolean = false>(options: Options<OpenLiveStreamData, ThrowOnError, OpenLiveStreamResponse>): Promise<ServerSentEventsResult<OpenLiveStreamResponses>> => (options.client ?? client).sse.get<OpenLiveStreamResponses, OpenLiveStreamErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/v1/live/stream',
    ...options
});

